class EMSsim(object):
    def __init__(self, name, port, host='localhost', rpc_debug=0, logging=False):
        super(EMSsim, self).__init__()
        self.name = name
        self.rpc_connection_name = "%s-rpc" % self.name
        self.evt_cb_name = None
        self.events = {}
        self.data_logger = None
        self.logger = None
        try:
            rpc_debug = int(os.environ['DEBUG_OM_RPC'])
        except Exception:
            pass
        if logging:
            emssim_logname = self.name + "-" + time.strftime("%Y%m%d_%H%M%S", time.localtime())
            logsystem.register_connection(connection_name=emssim_logname)
            self.data_logger = logging_system.getLogger("ruff.connection.%s" % emssim_logname)
            self.logger = ProcessSafeLogger(debug=rpc_debug)
        self.rpcL = JsonRpcLayer(port=port, host=host, logger=self.logger, data_logger=self.data_logger)
        registry.register_rpc_layer(self.rpcL, rpc_connection_name=self.rpc_connection_name)
        self.debug_event(info="CONSTRUCTED", owner="[%s]" % self.__class__.__name__)

    def __del__(self):
        try:
            self.debug_event(info="DELETED", owner="[%s]" % self.__class__.__name__)
        except Exception:
            #  Do not throw NoneType race condition exceptions during transport destruction
            pass

    def debug_event(self, *args, **kwargs):
        if self.logger:
            self.logger.debug_event(*args, **kwargs)

    def on_new_event(self, **data):
        if ('type' in data) and ('data' in data):
            event_type = data['type']
            if event_type in self.events:
                self.events[event_type]['storage'].append(data['data'])
                if self.events[event_type]['callback'] is not None:
                    try:
                        self.events[event_type]['callback'](data['data'])
                    except Exception:
                        pass
#       print("*** EVENTS=%s" % str(self.events))

    def subscribe_events(self, event_type, callback=None):
        self.register_events_callback()
        if event_type not in self.events:
            self.events[event_type] = {'callback': callback, 'storage': []}

    def unsubscribe_events(self, event_type):
        if event_type in self.events:
            del self.events[event_type]
            if len(self.events.keys()) == 0:
                self.unregister_events_callback()

    def get_events(self, event_type):
        if event_type in self.events:
            return self.events[event_type]['storage']
        return []

    def clear_events(self, event_type):
        if event_type in self.events:
            self.events[event_type]['storage'] = []

    def register_events_callback(self):
        if self.evt_cb_name:
            return True
        self.evt_cb_name = self.rpcL.register_method(self.on_new_event)
        result = self.rpcL.call('register_callback_handler',
                                notification=False,
                                timeout=60,
                                command_params={"callback_name": self.evt_cb_name})
        if ('status' in result) and (result['status'] == 'stopped'):
            return True
        return False

    def unregister_events_callback(self):
        self.rpcL.unregister_method(self.on_new_event, name=self.evt_cb_name)
        result = self.rpcL.call('unregister_callback_handler',
                                notification=False,
                                timeout=60,
                                command_params={"callback_name": self.evt_cb_name})
        self.evt_cb_name = None
        if ('status' in result) and (result['status'] == 'stopped'):
            return True
        return False

    def is_running(self):
        return self.rpcL.is_running()

    def check_hb(self):
        ret = False
        try:
            cmd_hb = EmssimCommand(method='hb', timeout=10, rpc_connection_name=self.rpc_connection_name)
            assert cmd_hb.run()
            ret = True
        except Exception:
            cmd_hb = EmssimCommand(method='test print "%s"' % self.name, timeout=10, rpc_connection_name=self.rpc_connection_name)
            ret = cmd_hb.run()
        return ret

